package com.oyuki.marketsquare.entity; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime; @Entity @Table(name="purchase_evidence") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class PurchaseEvidence { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) @JoinColumn(name="procurement_id",unique=true) private ProcurementRequest procurement; private String receiptUrl; private String goodsPhotoUrl; @Column(length=1500) private String notes; private LocalDateTime purchasedAt; private boolean correctProduct; private boolean correctQuantity; private boolean goodCondition; private boolean correctMeasurement; private boolean packagingSatisfactory; }